CREATE OR REPLACE FUNCTION kiyi_private.reward_day_next(last_day date, streak integer, today date)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$select case when last_day=today then streak when last_day=today-1 then streak+1 else 1 end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_identity_for(u uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare email text;k text;existing uuid;begin
 select lower(trim(a.email)) into email from auth.users a where a.id=u and a.email_confirmed_at is not null and not coalesce(a.is_anonymous,false);
 if email is null then raise exception 'Ödüller için e-posta adresini doğrula.' using errcode='42501';end if;
 select identity_key into k from kiyi_private.reward_identity where owner=u;if k is not null then return k;end if;
 -- Canonical aliases reduce self-invites; this is not a claim of identity verification.
 email=split_part(split_part(email,'@',1),'+',1)||'@'||replace(split_part(email,'@',2),'googlemail.com','gmail.com');
 if split_part(email,'@',2)='gmail.com' then email=replace(split_part(email,'@',1),'.','')||'@gmail.com';end if;
 select encode(extensions.hmac(email,salt,'sha256'),'hex') into k from kiyi_private.reward_settings;
 insert into kiyi_private.reward_identity(identity_key,owner) values(k,u) on conflict(identity_key) do nothing;
 select owner into existing from kiyi_private.reward_identity where identity_key=k;
 if existing is not null and existing<>u then raise exception 'Bu doğrulanmış kimlik için ödül hesabı zaten var.' using errcode='42501';end if;
 update kiyi_private.reward_identity set owner=u where identity_key=k and owner is null;
 return k;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_metrics(u uuid, baseline boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g int;c int;m int;p int;v int;f int;profile_ok int;custom int;begin
 select count(*),count(*)filter(where kind='car'),count(*)filter(where kind='motorcycle') into g,c,m from kiyi_private.reward_vehicles where owner=u;
 select count(*),count(*)filter(where media is not null and exists(select 1 from kiyi_private.media_registry mr where mr.path=q.media and mr.state='ready' and mr.mime like 'video/%')) into p,v from (
 select distinct on (md5(lower(regexp_replace(trim(s.text),'[[:space:]]+',' ','g'))||coalesce(s.media,''))) s.media,s.text from public.kiyi_posts s
 where s.author=u and not s.hidden and (baseline or (s.created<extract(epoch from(now()-interval '24 hours'))*1000 and (length(trim(s.text))>=12 or s.media is not null) and not exists(select 1 from public.kiyi_reports r where r.subject_kind='post' and r.subject_id=s.id and r.status in ('pending','in_review'))))
 order by md5(lower(regexp_replace(trim(s.text),'[[:space:]]+',' ','g'))||coalesce(s.media,'')),s.created limit 25)q;
 select count(*) into f from (select distinct coalesce(i.identity_key,a.id::text) from public.kiyi_follows x join auth.users a on a.id=x.follower left join kiyi_private.reward_identity i on i.owner=a.id
 where x.target=u and kiyi_private.account_active(a.id) and not kiyi_private.blocked(a.id,u) and (baseline or (a.email_confirmed_at is not null and a.created_at<now()-interval '7 days' and x.created_at<now()-interval '24 hours' and (select count(*) from kiyi_private.reward_days where owner=a.id)>=3)) limit 100)q;
 select case when length(trim(coalesce(profile->>'ownerName','')))>1 and length(trim(coalesce(profile->>'bio','')))>9 and coalesce(nullif(profile->>'avatar',''),nullif(profile->>'photo','')) is not null then 1 else 0 end into profile_ok from public.kiyi_profiles where user_id=u and deleted_at is null;
 select case when exists(select 1 from public.kiyi_vehicle_customizations vc join public.kiyi_vehicles ve on ve.id=vc.vehicle_id where ve.owner=u and vc.appearance<>'{}'::jsonb and (vc.version>1 or baseline)) or exists(select 1 from public.kiyi_ledger where owner=u and kind in ('appearance','vehicle_parts') and amount<0) then 1 else 0 end into custom;
 return jsonb_build_object('garage',g,'car',c,'motorcycle',m,'post',p,'video',v,'follower',f,'profile',coalesce(profile_ok,0),'customization',custom);
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_activity(u uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not kiyi_private.account_active(u) or not exists(select 1 from auth.users where id=u and email_confirmed_at is not null) then return;end if;
 begin perform kiyi_private.reward_identity_for(u);exception when insufficient_privilege then return;end;
 insert into kiyi_private.reward_days values(u,(now()at time zone 'Europe/Istanbul')::date)on conflict do nothing;
 perform kiyi_private.reward_sync(u);
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_erasure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin if new.deleted_at is not null and old.deleted_at is null then
 delete from kiyi_private.reward_days where owner=new.user_id;delete from kiyi_private.reward_daily where owner=new.user_id;
 delete from kiyi_private.reward_vehicles where owner=new.user_id;delete from kiyi_private.reward_vehicle_ids where owner=new.user_id;delete from kiyi_private.reward_vehicle_plates where owner=new.user_id;delete from kiyi_private.reward_codes where owner=new.user_id;
 delete from kiyi_private.reward_invites where invitee=new.user_id or referrer=new.user_id;
 delete from kiyi_private.reward_legacy where owner=new.user_id;
 end if;return new;end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_command(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid=auth.uid();k text;today date=(now() at time zone 'Europe/Istanbul')::date;d kiyi_private.reward_daily;next_streak int;idx int;coins int;code_value text;referrer_id uuid;metrics jsonb;before_value jsonb;after_value jsonb;begin
 if not kiyi_private.session_live(u) or not kiyi_private.account_active(u) or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'Geçerli bir hesap ve oturum gerekiyor.' using errcode='42501';end if;
 perform kiyi_private.social_rate(u,'rewards:'||action,case when action='reward_referral' then 5 else 15 end);
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 if action='reward_admin' then
 perform kiyi_private.admin_authorize('settings',true);
 if length(trim(coalesce(payload->>'reason','')))<10 then raise exception 'Değişiklik nedeni gerekli.';end if;
 select jsonb_build_object('daily',daily,'referral_amount',referral_amount,'monthly_cap',monthly_cap,'rules',(select jsonb_object_agg(code,amount)from kiyi_private.reward_rules)) into before_value from kiyi_private.reward_settings;
 if payload?'daily' then if jsonb_typeof(payload->'daily')<>'array' or jsonb_array_length(payload->'daily')<>30 or exists(select 1 from jsonb_array_elements_text(payload->'daily')x where x::int not between 0 and 500) then raise exception '30 günlük geçerli takvim gerekiyor.';end if;update kiyi_private.reward_settings set daily=array(select x::int from jsonb_array_elements_text(payload->'daily')x);end if;
 if payload?'referral_amount' then update kiyi_private.reward_settings set referral_amount=(payload->>'referral_amount')::int;end if;
 if payload?'monthly_cap' then update kiyi_private.reward_settings set monthly_cap=(payload->>'monthly_cap')::int;end if;
 if payload?'rules' then update kiyi_private.reward_rules r set amount=(payload->'rules'->>r.code)::int where payload->'rules'?r.code;end if;
 select jsonb_build_object('daily',daily,'referral_amount',referral_amount,'monthly_cap',monthly_cap,'rules',(select jsonb_object_agg(code,amount)from kiyi_private.reward_rules)) into after_value from kiyi_private.reward_settings;
 insert into kiyi_private.reward_config_audit(actor,before_value,after_value,reason)values(u,before_value,after_value,left(payload->>'reason',400));return '{"ok":true}';end if;
 if not exists(select 1 from auth.users where id=u and email_confirmed_at is not null) then
 if action='rewards' then return jsonb_build_object('verification_required',true);end if;
 raise exception 'Ödüller için e-posta adresini doğrula.' using errcode='42501';end if;
 k=kiyi_private.reward_identity_for(u);
 insert into kiyi_private.reward_codes(owner)values(u)on conflict do nothing;
 if action='reward_referral' then
 code_value=upper(regexp_replace(coalesce(payload->>'code',''),'[[:space:]-]','','g'));
 if code_value !~ '^[A-F0-9]{16}$' then raise exception 'Geçersiz davet kodu.' using errcode='22023';end if;
 select owner into referrer_id from kiyi_private.reward_codes where code=code_value;
 if referrer_id is null or referrer_id=u or not kiyi_private.account_active(referrer_id) or kiyi_private.blocked(u,referrer_id) then raise exception 'Bu davet kullanılamaz.' using errcode='22023';end if;
 if exists(select 1 from kiyi_private.reward_invites where invitee=u) then
 if exists(select 1 from kiyi_private.reward_invites where invitee=u and referrer=referrer_id) then return '{"ok":true,"already_bound":true}';end if;
 raise exception 'Hesabına zaten bir davet bağlanmış.' using errcode='22023';end if;
 if not exists(select 1 from auth.users a,auth.users b,kiyi_private.reward_settings s where a.id=u and b.id=referrer_id and a.created_at>=s.started_at and a.created_at>now()-interval '7 days' and b.created_at<a.created_at) then raise exception 'Davetler yalnızca yeni hesaplara bağlanabilir.' using errcode='22023';end if;
 -- New users may bind within the existing seven-day window, including after plate entry.
 update kiyi_private.reward_identity set invite_used=true where identity_key=k and not invite_used;if not found then raise exception 'Bu kimlik için davet daha önce kullanılmış.' using errcode='22023';end if;
 insert into kiyi_private.reward_invites(invitee,referrer,identity_key)values(u,referrer_id,k);return '{"ok":true}';
 elsif action='reward_daily' then
 insert into kiyi_private.reward_daily(owner)values(u)on conflict do nothing;
 select * into d from kiyi_private.reward_daily where owner=u for update;
 if d.last_day=today then return jsonb_build_object('ok',true,'already_claimed',true,'balance',(select balance from public.kiyi_wallets where user_id=u));end if;
 next_streak=kiyi_private.reward_day_next(d.last_day,d.streak,today);idx=(next_streak-1)%30+1;
 select daily[idx] into coins from kiyi_private.reward_settings;
 if not kiyi_private.reward_pay(u,'daily:'||today::text,coins) then return jsonb_build_object('ok',true,'already_claimed',true);end if;
 update kiyi_private.reward_daily set last_day=today,streak=next_streak where owner=u;
 perform kiyi_private.reward_activity(u);
 return jsonb_build_object('ok',true,'amount',coins,'day',idx,'streak',next_streak,'balance',(select balance from public.kiyi_wallets where user_id=u));
 elsif action<>'rewards' then raise exception 'Geçersiz ödül işlemi.';end if;
 perform kiyi_private.reward_sync(u);perform kiyi_private.reward_settle(u);
 select * into d from kiyi_private.reward_daily where owner=u;
 next_streak=kiyi_private.reward_day_next(d.last_day,coalesce(d.streak,0),today);idx=(next_streak-1)%30+1;metrics=kiyi_private.reward_metrics(u);
 return jsonb_build_object('verified',coalesce((select verified from public.kiyi_entitlements where user_id=u),false),'today',today,'timezone','Europe/Istanbul','claimed',coalesce(d.last_day=today,false),'day',idx,'streak',case when d.last_day>=today-1 then d.streak else 0 end,'calendar',(select to_jsonb(daily)from kiyi_private.reward_settings),'code',(select code from kiyi_private.reward_codes where owner=u),'balance',(select balance from public.kiyi_wallets where user_id=u),
 'referral_amount',(select referral_amount from kiyi_private.reward_settings),'monthly_cap',(select monthly_cap from kiyi_private.reward_settings),'referral_earned',(select coalesce(sum(amount),0) from kiyi_private.reward_awards where owner=u and award_key like 'invite:%'),
 'invites',coalesce((select jsonb_agg(jsonb_build_object('number',q.n,'days',q.days,'plate_added',q.plate_added,'paid',q.paid_at is not null,'created_at',q.created_at))from(select row_number()over(order by created_at) n,created_at,paid_at,(kiyi_private.reward_invite_plate(i.invitee) is not null) plate_added,(select count(*)from kiyi_private.reward_days activity where activity.owner=i.invitee and activity.day>=(i.created_at at time zone 'Europe/Istanbul')::date) days from kiyi_private.reward_invites i where referrer=u order by created_at desc limit 100)q),'[]'),
 'achievements',coalesce((select jsonb_agg(jsonb_build_object('code',r.code,'title',r.title,'category',r.category,'threshold',r.threshold,'amount',r.amount,'progress',least(r.threshold,(metrics->>r.category)::int),'earned',a.award_key is not null,'legacy',coalesce(a.legacy,false))order by r.position)from kiyi_private.reward_rules r left join kiyi_private.reward_awards a on a.identity_key=k and a.award_key='achievement:'||r.code),'[]'));
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_pay(u uuid, k text, coins integer, old boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity text;rid uuid=gen_random_uuid();changed int;begin
 if coins<0 or coins>500 then raise exception 'Geçersiz ödül.';end if;
 identity=kiyi_private.reward_identity_for(u);
 insert into kiyi_private.reward_awards(identity_key,award_key,owner,amount,ledger_id,legacy) values(identity,k,u,case when old then 0 else coins end,case when coins>0 and not old then rid else null end,old) on conflict do nothing;
 get diagnostics changed=row_count;if changed=0 then return false;end if;
 if coins>0 and not old then
 insert into public.kiyi_wallets(user_id,balance)values(u,0)on conflict do nothing;
 update public.kiyi_wallets set balance=balance+coins where user_id=u;
 insert into public.kiyi_ledger(id,owner,request_id,amount,kind,reference) values(rid,u,rid,coins,'reward',k);
 end if;return true;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_sync(u uuid, baseline boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare metrics jsonb;r record;paid boolean;begin
 if not kiyi_private.account_active(u) or not exists(select 1 from auth.users where id=u and email_confirmed_at is not null) then return;end if;
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 begin perform kiyi_private.reward_identity_for(u);exception when insufficient_privilege then return;end;
 metrics=kiyi_private.reward_metrics(u,baseline);
 for r in select * from kiyi_private.reward_rules order by position loop
 if (metrics->>r.category)::int>=r.threshold or (baseline and exists(select 1 from public.kiyi_badges where owner=u and code=r.code)) then
 paid=kiyi_private.reward_pay(u,'achievement:'||r.code,r.amount,baseline or exists(select 1 from kiyi_private.reward_legacy where owner=u and r.code=any(codes)));
 insert into public.kiyi_badges(owner,code)values(u,r.code)on conflict do nothing;
 -- Do not replay historical badge notices. Existing social triggers still own their notices.
 end if;end loop;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.command_before_badge_levels(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;begin
 if action in ('rewards','reward_daily','reward_referral','reward_admin') then perform kiyi_private.command_before_rewards('__stage7_guard','{}');return kiyi_private.reward_command(action,payload);end if;
 r=kiyi_private.command_before_rewards(action,payload);
 if action in ('profile','vehicle_create','vehicle_update','vehicle_parts','vehicle_apply','vehicle_customize','vehicle_part_purchase','post_create','comment_create','comment','follow','gift','appearance') then perform kiyi_private.reward_activity(auth.uid());end if;
 return r;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_process_invites()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;n int=0;begin
 for u in select distinct i.referrer from kiyi_private.reward_invites i cross join kiyi_private.reward_settings c where i.paid_at is null
 and kiyi_private.reward_invite_plate(i.invitee) is not null
 and (select count(*)from kiyi_private.reward_awards a where a.owner=i.referrer and a.award_key like 'invite:%'and not a.legacy and a.created_at>=date_trunc('month',now()at time zone 'Europe/Istanbul')at time zone 'Europe/Istanbul')<c.monthly_cap
 order by i.referrer limit 100 loop
 perform kiyi_private.reward_settle(u);n=n+1;
 end loop;return n;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_vehicle_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare inserted int;new_plate int;begin
 if new.deleted_at is null and new.model_id is not null and new.plate_key is not null then
 insert into kiyi_private.reward_vehicle_plates values(new.owner,md5(new.plate_key))on conflict do nothing;get diagnostics new_plate=row_count;
 insert into kiyi_private.reward_vehicle_ids values(new.owner,new.id)on conflict do nothing;get diagnostics inserted=row_count;
 if inserted>0 and new_plate>0 then insert into kiyi_private.reward_vehicles values(new.owner,md5(new.plate_key),new.kind)on conflict do nothing;end if;
 end if;return new;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.badge_erasure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if new.deleted_at is not null then delete from kiyi_private.badge_map_days where owner=new.user_id;delete from kiyi_private.badge_facts where owner=new.user_id;delete from kiyi_private.badge_earned where owner=new.user_id;end if;return new;end$function$
CREATE OR REPLACE FUNCTION kiyi_private.badge_map_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.region in('konyaalti','lara','kultur') and new.received_at>now()-interval '90 seconds'
 and exists(select 1 from public.kiyi_privacy where user_id=new.user_id and sharing and not ghost and consented_at is not null)
 and exists(select 1 from auth.users where id=new.user_id and email_confirmed_at is not null) and kiyi_private.account_active(new.user_id) then
 insert into kiyi_private.badge_map_days(owner,region,day)values(new.user_id,new.region,(now()at time zone 'Europe/Istanbul')::date)on conflict do nothing;
 end if;return new;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.badge_privacy_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if new.ghost then insert into kiyi_private.badge_facts(owner,code)values(new.user_id,'ghost_mode')on conflict do nothing;end if;return new;end$function$
CREATE OR REPLACE FUNCTION kiyi_private.badge_sync(u uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m jsonb;r record;n int;qualified boolean;begin
 if not kiyi_private.account_active(u) then return '{}';end if;
 perform pg_advisory_xact_lock(hashtextextended('kiyi-badges:'||u::text,0));m=kiyi_private.badge_metrics(u);
 for r in select * from kiyi_private.badge_catalog order by position loop
 n=coalesce((m->>r.metric)::int,0);qualified=n>=r.threshold and (r.code<>'map_ultra' or (m->>'map_regions')::int=3);
 -- Preserve old single-badge achievements; only new tiers are recalculated after invalidation/deletion.
 if r.level is null and r.code not in('verified','premium_member') and exists(select 1 from public.kiyi_badges where owner=u and code=r.code) then qualified=true;end if;
 if qualified then insert into kiyi_private.badge_earned(owner,code)values(u,r.code)on conflict(owner,code)do update set active=true;
 else update kiyi_private.badge_earned set active=false where owner=u and code=r.code;end if;
 end loop;return m;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.badge_valid_posts(u uuid)
 RETURNS TABLE(id uuid, media text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select distinct on(md5(lower(regexp_replace(trim(p.text),'[[:space:]]+',' ','g'))||coalesce(p.media,''))) p.id,p.media from public.kiyi_posts p
 where p.author=u and not p.hidden and p.created<extract(epoch from now()-interval '24 hours')*1000
 and (length(trim(p.text))>=12 or p.media is not null)
 and (p.media is null or exists(select 1 from kiyi_private.media_registry m where m.path=p.media and m.owner=u and m.state='ready'))
 and not exists(select 1 from public.kiyi_reports r where r.subject_kind='post' and r.subject_id=p.id and r.status in('pending','in_review'))
 and not exists(select 1 from kiyi_private.badge_invalidations i where i.kind='post' and i.subject=p.id)
 order by md5(lower(regexp_replace(trim(p.text),'[[:space:]]+',' ','g'))||coalesce(p.media,'')),p.created,p.id
$function$
CREATE OR REPLACE FUNCTION kiyi_private.command(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid=auth.uid();t uuid;result jsonb;metrics jsonb;items jsonb;begin
 if action='badge_dashboard' then
 perform kiyi_private.command_before_rewards('__stage7_guard','{}');
 if not kiyi_private.session_live(u)or not kiyi_private.account_active(u)or coalesce((auth.jwt()->>'is_anonymous')::boolean,false)then raise exception 'Geçerli bir hesap gerekiyor.'using errcode='42501';end if;
 perform kiyi_private.social_rate(u,'badge_dashboard',20);metrics=kiyi_private.badge_sync(u);
 select jsonb_agg(to_jsonb(c)-'metric'-'position'||jsonb_build_object('progress',least(c.threshold,coalesce((metrics->>c.metric)::int,0)),'earned',coalesce(b.active,false),'earned_at',case when b.active then b.earned_at else null end,'extra_ready',c.code<>'map_ultra'or(metrics->>'map_regions')::int=3)order by c.position)into items from kiyi_private.badge_catalog c left join kiyi_private.badge_earned b on b.code=c.code and b.owner=u;
 return jsonb_build_object('items',items,'earned',(select count(*)from kiyi_private.badge_earned where owner=u and active),'total',(select count(*)from kiyi_private.badge_catalog));
 elsif action='badge_invalidate' then
 perform kiyi_private.command_before_rewards('__stage7_guard','{}');perform kiyi_private.admin_authorize('ops.write',true);
 if payload->>'kind' not in('gift','post','comment','invite')or length(trim(coalesce(payload->>'reason','')))<10 then raise exception 'Geçerli kayıt ve gerekçe gerekli.';end if;
 insert into kiyi_private.badge_invalidations(kind,subject,actor,reason)values(payload->>'kind',(payload->>'id')::uuid,u,left(payload->>'reason',400))on conflict do nothing;return '{"ok":true}';
 end if;
 result=kiyi_private.command_before_badge_levels(action,payload);
 if action='badges' then
 t=coalesce(nullif(payload->>'target','')::uuid,u);
 -- The delegated badges read already enforces profile visibility/block/ghost rules.
 if t=u then metrics=kiyi_private.badge_sync(u);else metrics=kiyi_private.badge_metrics(t);end if;
 return result||jsonb_build_object('level_badges',coalesce((select jsonb_agg(jsonb_build_object('code',b.code,'earned_at',b.earned_at,'title',c.title,'level',c.level,'image',c.image)order by c.position)from kiyi_private.badge_earned b join kiyi_private.badge_catalog c on c.code=b.code where b.owner=t and b.active and ((c.level is null and c.code not in('verified','premium_member')) or (coalesce((metrics->>c.metric)::int,0)>=c.threshold and (c.code<>'map_ultra' or (metrics->>'map_regions')::int=3)))),'[]'));
 end if;return result;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_invite_plate(u uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select md5(v.plate_key) from public.kiyi_vehicles v
 where v.owner=u and v.deleted_at is null and v.model_id is not null and nullif(v.plate_key,'') is not null
 and not exists(select 1 from kiyi_private.reward_vehicle_plates h where h.plate_hash=md5(v.plate_key) and h.owner<>u)
 and not exists(select 1 from kiyi_private.reward_invite_plates h where h.plate_hash=md5(v.plate_key) and h.invitee is distinct from u)
 order by v.created_at,v.id limit 1
$function$
CREATE OR REPLACE FUNCTION kiyi_private.reward_settle(u uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;n int;coins int;cap int;plate_hash_value text;reserved uuid;
 month_start timestamptz=date_trunc('month',now() at time zone 'Europe/Istanbul') at time zone 'Europe/Istanbul';begin
 if not kiyi_private.account_active(u) then return;end if;
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 select referral_amount,monthly_cap into coins,cap from kiyi_private.reward_settings;
 select count(*) into n from kiyi_private.reward_awards where owner=u and award_key like 'invite:%' and not legacy and created_at>=month_start;
 for r in select * from kiyi_private.reward_invites where referrer=u and paid_at is null order by created_at,invitee loop
 exit when n>=cap;
 if not kiyi_private.account_active(r.invitee) or kiyi_private.blocked(u,r.invitee)
 or not exists(select 1 from auth.users where id=r.invitee and email_confirmed_at is not null and not coalesce(is_anonymous,false))
 or exists(select 1 from kiyi_private.badge_invalidations where kind='invite' and subject=r.invitee) then continue;end if;
 plate_hash_value=kiyi_private.reward_invite_plate(r.invitee);
 if plate_hash_value is null then continue;end if;
 insert into kiyi_private.reward_invite_plates(plate_hash,invitee)values(plate_hash_value,r.invitee)on conflict do nothing;
 select invitee into reserved from kiyi_private.reward_invite_plates where plate_hash=plate_hash_value;
 if reserved is distinct from r.invitee then continue;end if;
 if kiyi_private.reward_pay(u,'invite:'||r.identity_key,coins) then n=n+1;end if;
 update kiyi_private.reward_invites set paid_at=now() where invitee=r.invitee;
 end loop;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.badge_metrics(u uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare metrics jsonb;posts int;photos int;videos int;likes int;comments int;gifts int;songs int;invites int;mk int;ml int;mc int;base_metrics jsonb;begin
 base_metrics=kiyi_private.reward_metrics(u);
 select count(*),count(*)filter(where exists(select 1 from kiyi_private.media_registry m where m.path=p.media and m.mime like 'image/%')),count(*)filter(where exists(select 1 from kiyi_private.media_registry m where m.path=p.media and m.mime like 'video/%')) into posts,photos,videos from kiyi_private.badge_valid_posts(u)p;
 select count(*) into likes from public.kiyi_likes l join kiyi_private.badge_valid_posts(u)p on p.id=l.post join auth.users a on a.id=l.person where l.person<>u and a.email_confirmed_at is not null and a.created_at<now()-interval '24 hours' and kiyi_private.account_active(l.person) and not kiyi_private.blocked(u,l.person);
 select count(*) into comments from (select distinct lower(regexp_replace(trim(c.text),'[[:space:]]+',' ','g')) from public.kiyi_comments c join public.kiyi_posts p on p.id=c.post where c.author=u and not c.hidden and not p.hidden and kiyi_private.account_active(p.author) and not kiyi_private.blocked(u,p.author) and length(trim(c.text))>=3 and c.created<extract(epoch from now()-interval '24 hours')*1000 and not exists(select 1 from public.kiyi_reports r where r.subject_kind='comment'and r.subject_id=c.id and r.status in('pending','in_review')) and not exists(select 1 from kiyi_private.badge_invalidations i where i.kind='comment'and i.subject=c.id))q;
 select count(*)filter(where g.product<>'song'),count(*)filter(where g.product='song') into gifts,songs from public.kiyi_gifts g
 where g.sender=u and g.recipient<>u and kiyi_private.account_active(g.recipient)
 and exists(select 1 from public.kiyi_ledger l where l.owner=u and l.kind='gift' and l.request_id=g.id and l.amount=-g.credits and l.reference=g.id::text)
 and not exists(select 1 from public.kiyi_ledger l where l.owner=u and l.amount>0 and l.kind in('refund','gift_refund') and (l.reference=g.id::text or l.reference='gift:'||g.id::text))
 and not exists(select 1 from kiyi_private.badge_invalidations i where i.kind='gift'and i.subject=g.id);
 select count(*) into invites from kiyi_private.reward_invites i join auth.users a on a.id=i.invitee where i.referrer=u and a.email_confirmed_at is not null and kiyi_private.account_active(i.invitee) and not kiyi_private.blocked(u,i.invitee) and kiyi_private.reward_invite_plate(i.invitee) is not null and not exists(select 1 from kiyi_private.badge_invalidations v where v.kind='invite'and v.subject=i.invitee);
 select count(*)filter(where region='konyaalti'),count(*)filter(where region='lara'),count(*)filter(where region='kultur')into mk,ml,mc from kiyi_private.badge_map_days where owner=u;
 metrics=base_metrics||jsonb_build_object('post',posts,'photo',photos,'video',videos,'like',likes,'comment',comments,'gift',gifts,'song',songs,'invite',invites,'map_konyaalti',mk,'map_lara',ml,'map_kultur',mc,'map_total',mk+ml+mc,'map_regions',(case when mk>0 then 1 else 0 end)+(case when ml>0 then 1 else 0 end)+(case when mc>0 then 1 else 0 end),'daily',case when exists(select 1 from kiyi_private.reward_awards where owner=u and award_key like 'daily:%'and not legacy)then 1 else 0 end,'verified',case when exists(select 1 from public.kiyi_entitlements where user_id=u and verified)then 1 else 0 end,'premium',case when kiyi_private.premium(u)then 1 else 0 end,'ghost',case when exists(select 1 from kiyi_private.badge_facts where owner=u and code='ghost_mode')or exists(select 1 from public.kiyi_privacy where user_id=u and ghost)then 1 else 0 end);
 return metrics;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.command_pre_garage(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid=auth.uid();t uuid;rid uuid;prod text;cost integer;bal bigint;existing jsonb;item text;input_profile jsonb;person jsonb;arr jsonb;postid uuid;post_record public.kiyi_posts;out jsonb;ms bigint=(extract(epoch from clock_timestamp())*1000)::bigint;is_premium boolean;reg text;la double precision;lo double precision;pref jsonb;names jsonb;v text;
begin
 if u is null or not exists(select 1 from auth.users where id=u) then raise exception 'Giriş yapmalısın.' using errcode='42501';end if;
 if action in ('ops_config','support_create','privacy_request','appeal_create','sanctions_mine','cases_mine','plate_change_request') then return kiyi_private.user_operations(action,payload);end if;
 if exists(select 1 from public.kiyi_profiles where user_id=u and deleted_at is not null) then raise exception 'Kıyı hesabın silinmiş.' using errcode='42501';end if;
 if coalesce((select value='true'::jsonb from kiyi_private.ops_settings where key='maintenance'),false) then raise exception 'Kıyı kısa süreli bakımda. Biraz sonra yeniden dene.';end if;
 if exists(select 1 from public.kiyi_entitlements where user_id=u and suspended and (suspended_until is null or suspended_until>now())) then raise exception 'Hesabın kullanıma kapalı.' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 insert into public.kiyi_profiles(user_id,username) values(u,'kiyi_'||left(replace(u::text,'-',''),24)) on conflict(user_id) do nothing;
 insert into public.kiyi_wallets values(u,0) on conflict do nothing;
 insert into public.kiyi_appearance(user_id) values(u) on conflict do nothing;
 insert into public.kiyi_privacy(user_id) values(u) on conflict do nothing;
 is_premium=kiyi_private.premium(u);
 insert into kiyi_private.ops_presence(user_id,last_seen) values(u,now()) on conflict(user_id)do update set last_seen=now() where kiyi_private.ops_presence.last_seen<now()-interval '1 minute';
 if action in ('bundle','profile','post_create','gift') then insert into kiyi_private.ops_activity values(u,(now() at time zone 'Europe/Istanbul')::date) on conflict do nothing;end if;
 if action='__stage7_guard' then return jsonb_build_object('ok',true);end if;
 if payload?'target' then t=(payload->>'target')::uuid;end if;
 if action='vehicle_model' then
  prod=payload->>'model';
  if prod is null or not exists(select 1 from public.kiyi_vehicle_models m where m.id=prod and m.kind='car' and m.ready) then raise exception 'Geçersiz araç modeli.' using errcode='22023';end if;
  if t is not null and t<>u then raise exception 'Yalnızca kendi aracını düzenleyebilirsin.' using errcode='42501';end if;
  update public.kiyi_appearance set vehicle_model=prod where user_id=u;
  update public.kiyi_profiles set profile=profile||jsonb_build_object('car',(select name from public.kiyi_vehicle_models where id=prod)) where user_id=u;
  return jsonb_build_object('ok',true,'vehicleModel',prod);
 elsif action='profile_photos' then
  t=coalesce(t,u);
  if t<>u and (not exists(select 1 from public.kiyi_profiles where user_id=t and searchable and deleted_at is null) or not kiyi_private.account_active(t) or kiyi_private.blocked(u,t)) then raise exception 'Profil bulunamadı.' using errcode='42501';end if;
  return jsonb_build_object('photos',coalesce((select jsonb_agg(s.path order by s.n) from public.kiyi_profiles p cross join lateral jsonb_array_elements_text(case when jsonb_typeof(p.profile->'photos')='array' then p.profile->'photos' else case when coalesce(p.profile->>'avatar','')<>'' then jsonb_build_array(p.profile->>'avatar') else '[]'::jsonb end end)with ordinality s(path,n) where p.user_id=t and not exists(select 1 from kiyi_private.ops_media where path=s.path and hidden)),'[]'));
 elsif action='profile_photo_cleanup' then
  arr=payload->'photos';if jsonb_typeof(arr) is distinct from 'array' or jsonb_array_length(arr)>3 then raise exception 'Geçersiz fotoğraf listesi.';end if;
  return jsonb_build_object('photos',coalesce((select jsonb_agg(s) from jsonb_array_elements_text(arr)s where split_part(s,'/',1)=u::text and not exists(select 1 from public.kiyi_profiles p where p.profile->>'avatar'=s or p.profile->>'photo'=s or coalesce(p.profile->'photos','[]'::jsonb)?s) and not exists(select 1 from public.kiyi_posts where media=s)),'[]'));
 elsif action='profile_photos_update' then
  arr=payload->'photos';
  if jsonb_typeof(arr) is distinct from 'array' then raise exception 'En fazla üç profil fotoğrafı seç.';end if;
  if jsonb_array_length(arr)>3 or exists(select 1 from jsonb_array_elements(arr)s where jsonb_typeof(s)<>'string') or (select count(distinct s) from jsonb_array_elements_text(arr)s)<>jsonb_array_length(arr) then raise exception 'En fazla üç farklı profil fotoğrafı seç.';end if;
  if exists(select 1 from jsonb_array_elements_text(arr)s where length(s)>150 or split_part(s,'/',1)<>u::text or not exists(select 1 from storage.objects o where o.bucket_id='kiyi-media' and o.name=s and coalesce(o.metadata->>'mimetype','') in ('image/jpeg','image/png','image/webp'))) then raise exception 'Fotoğraf sana ait değil veya dosya türü desteklenmiyor.' using errcode='42501';end if;
  update public.kiyi_profiles set profile=profile||jsonb_build_object('photos',arr,'avatar',coalesce(arr->>0,'')) where user_id=u;
  return jsonb_build_object('ok',true);
 elsif action='profile' then
  input_profile=coalesce(payload->'profile','{}');pref='{}';
  if input_profile?'photos' then raise exception 'Fotoğrafları profil fotoğrafı ekranından düzenle.';end if;
  if input_profile?'avatar' and exists(select 1 from public.kiyi_profiles where user_id=u and profile?'photos') and input_profile->>'avatar' is distinct from (select profile->>'avatar' from public.kiyi_profiles where user_id=u) then raise exception 'Fotoğrafları profil fotoğrafı ekranından düzenle.';end if;
  if input_profile?'plate' and exists(select 1 from public.kiyi_verifications where user_id=u and status='approved') and regexp_replace(upper(input_profile->>'plate'),'\s','','g') is distinct from (select plate_key from public.kiyi_profiles where user_id=u) then raise exception 'Doğrulanmış plakan için değişiklik talebi gönder.';end if;
  if input_profile?'plate' and length(coalesce(input_profile->>'plate',''))>30 then raise exception 'Plakanı kontrol et.';end if;
  foreach v in array array['name','ownerName','plate','car','year','color','area','bio','instagram','tiktok','status','avatar','photo'] loop
   if input_profile?v then
    if v in ('avatar','photo') and coalesce(input_profile->>v,'')<>'' and not exists(select 1 from storage.objects where bucket_id='kiyi-media' and name=input_profile->>v and split_part(name,'/',1)=u::text) then raise exception 'Fotoğraf sana ait değil.';end if;
    pref=pref||jsonb_build_object(v,left(coalesce(input_profile->>v,''),case when v in ('avatar','photo') then 150 else 500 end));
   end if;
  end loop;
  update public.kiyi_profiles set profile=public.kiyi_profiles.profile||pref,username=coalesce(nullif(payload->>'username',''),username),searchable=coalesce((payload->>'searchable')::boolean,searchable) where user_id=u;
  return kiyi_private.person(u);
 elsif action='directory' then
  return jsonb_build_object('profiles',coalesce((select jsonb_agg(kiyi_private.person(p.user_id)) from (select * from public.kiyi_profiles where user_id<>u and searchable and kiyi_private.account_active(user_id) and not kiyi_private.blocked(user_id,u) and (not(payload?'plate') or regexp_replace(upper(profile->>'plate'),'\s','','g')=regexp_replace(upper(payload->>'plate'),'\s','','g')) order by created_at desc limit 100)p),'[]'));
 elsif action in ('follow','favorite','block','approve') then
  if t=u or not exists(select 1 from public.kiyi_profiles where user_id=t) then raise exception 'Kullanıcı bulunamadı.';end if;
  if action='block' then
   if coalesce((payload->>'enabled')::boolean,true) then insert into public.kiyi_blocks values(u,t) on conflict do nothing;delete from public.kiyi_follows where (follower=u and target=t)or(follower=t and target=u);delete from public.kiyi_favorites where(owner=u and target=t)or(owner=t and target=u);update public.kiyi_privacy set approved=array_remove(approved,t) where user_id=u;update public.kiyi_privacy set approved=array_remove(approved,u) where user_id=t;
   else delete from public.kiyi_blocks where owner=u and target=t;end if;
  elsif kiyi_private.blocked(u,t) then raise exception 'Bu işlem yapılamaz.';
  elsif action='follow' then if (payload->>'enabled')::boolean then insert into public.kiyi_follows(follower,target) values(u,t) on conflict do nothing;else delete from public.kiyi_follows where follower=u and target=t;end if;
  elsif action='favorite' then if (payload->>'enabled')::boolean then insert into public.kiyi_favorites values(u,t) on conflict do nothing;else delete from public.kiyi_favorites where owner=u and target=t;end if;
  else update public.kiyi_privacy set approved=case when (payload->>'enabled')::boolean then array_append(array_remove(approved,t),t) else array_remove(approved,t) end where user_id=u;end if;
  return jsonb_build_object('ok',true);
 elsif action='remove_follower' then delete from public.kiyi_follows where follower=t and target=u;return jsonb_build_object('ok',true);
 elsif action='appearance' then
  item=payload->>'kind';prod=payload->>'value';cost=0;
  if item='plate' then
   if prod is null or prod not in ('classic','diamond','kiss','named','carbon','chrome') then raise exception 'Geçersiz plaka.';end if;
   if prod in ('kiss','named','carbon','chrome') and length(trim(coalesce(payload->>'name',''))) not between 1 and 20 then raise exception 'Plaka yazısı 1–20 karakter olmalı.';end if;
   if prod<>'classic' then select credits into cost from public.kiyi_products where id='plate' and active;if not found then raise exception 'Plaka özelleştirme kapalı.';end if;end if;
  elsif item='color' then if prod is null or prod !~ '^#[0-9a-f]{6}$' then raise exception 'Geçersiz renk.';end if;if prod not in ('#ffffff','#20242b') then select credits into cost from public.kiyi_products where id='car_color' and active;if not found then raise exception 'Araç rengi özelleştirme kapalı.';end if;end if;
  elsif item='frame' then if prod is null or prod not in ('none','leopard','diamond','blossom','kitty','web','alert','bluekitty','starlight') then raise exception 'Geçersiz çerçeve.';end if;
  else raise exception 'Geçersiz ürün.';end if;
  if cost>0 and not exists(select 1 from public.kiyi_inventory where owner=u and sku=item||':'||prod) then
   rid=(payload->>'request_id')::uuid;if rid is null then raise exception 'İşlem kimliği gerekiyor.';end if;
   if exists(select 1 from public.kiyi_ledger where owner=u and request_id=rid) then raise exception 'Bu işlem kimliği kullanılmış.';end if;
   update public.kiyi_wallets set balance=balance-cost where user_id=u and balance>=cost returning balance into bal;
   if not found then raise exception 'Yeterli jeton yok.';end if;
   insert into public.kiyi_inventory(owner,sku) values(u,item||':'||prod);
   insert into public.kiyi_ledger(owner,request_id,amount,kind,reference) values(u,rid,-cost,'appearance',item||':'||prod);
  end if;
  if item='plate' then update public.kiyi_appearance set plate_style=prod,plate_names=case when prod in ('kiss','named','carbon','chrome') then plate_names||jsonb_build_object(prod,trim(payload->>'name')) else plate_names end where user_id=u;
  elsif item='color' then update public.kiyi_appearance set paint=prod where user_id=u;
  else update public.kiyi_appearance set frame=prod where user_id=u;end if;
  return kiyi_private.person(u);
 elsif action='gift' then
  if t=u or not exists(select 1 from public.kiyi_profiles where user_id=t and searchable and kiyi_private.account_active(t)) or kiyi_private.blocked(u,t) then raise exception 'Alıcıya hediye gönderilemiyor.';end if;
  rid=(payload->>'request_id')::uuid;if rid is null then raise exception 'İşlem kimliği gerekiyor.';end if;
  select to_jsonb(g) into existing from public.kiyi_gifts g where id=rid and sender=u;if found then if existing->>'recipient' is distinct from t::text or existing->>'product' is distinct from payload->>'product' or existing->'song' is distinct from (case when payload->>'product'='song' then payload->'song' else 'null'::jsonb end) then raise exception 'Bu işlem kimliği başka bir hediye için kullanılmış.';end if;return existing;end if;
  if coalesce((select value='false'::jsonb from kiyi_private.ops_settings where key='gifts_enabled'),false) then raise exception 'Hediye gönderimi kısa süreli kapalı.';end if;
  prod=payload->>'product';if prod='song' and coalesce((select value='false'::jsonb from kiyi_private.ops_settings where key='songs_enabled'),false) then raise exception 'Şarkı gönderimi kısa süreli kapalı.';end if;select credits into cost from public.kiyi_products where id=prod and kind in ('gift','song') and active;if not found then raise exception 'Geçersiz hediye.';end if;
  if prod='song' then
   if jsonb_typeof(payload->'song') is distinct from 'object'
    or payload->'song'->>'source' is distinct from 'manual'
    or jsonb_typeof(payload->'song'->'title') is distinct from 'string'
    or length(btrim(coalesce(payload->'song'->>'title',''))) not between 1 and 150
    or length(coalesce(payload->'song'->>'artist',''))>150
    or coalesce(payload->'song'->>'url','')<>''
    or coalesce(payload->'song'->>'artwork','')<>''
   then raise exception 'Şarkı adını yaz (en fazla 150 karakter).';end if;
   if octet_length((payload->'song')::text)>3000 then raise exception 'Şarkı verisi çok büyük.';end if;
  end if;
  update public.kiyi_wallets set balance=balance-cost where user_id=u and balance>=cost returning balance into bal;if not found then raise exception 'Yeterli jeton yok.';end if;
  insert into public.kiyi_gifts values(rid,u,t,prod,cost,case when prod='song' then payload->'song' else null end,ms);
  insert into public.kiyi_ledger(owner,request_id,amount,kind,reference) values(u,rid,-cost,'gift',rid::text);
  insert into public.kiyi_notifications(recipient,sender,kind,gift_id,created) values(t,u,'gift',rid,ms);
  return (select to_jsonb(g) from public.kiyi_gifts g where id=rid);
 elsif action='read' then update public.kiyi_notifications set read_at=now() where recipient=u and id=(payload->>'id')::uuid;return jsonb_build_object('ok',true);
 elsif action='visit' then
  if t<>u and exists(select 1 from public.kiyi_profiles where user_id=t and searchable) and not kiyi_private.blocked(u,t) then insert into public.kiyi_visits values(t,u,ms) on conflict(owner,visitor) do update set visited=excluded.visited;end if;return jsonb_build_object('ok',true);
 elsif action='visits' then if not is_premium then raise exception 'Profiline bakanları görmek için Premium gerekiyor.' using errcode='PT402';end if; return jsonb_build_object('visitors',coalesce((select jsonb_agg(jsonb_build_object('id',visitor,'visited',visited,'profile',kiyi_private.person(visitor))) from (select * from public.kiyi_visits where owner=u and not kiyi_private.blocked(u,visitor) order by visited desc limit 100)v),'[]'));
 elsif action='report' then
  if t=u or not exists(select 1 from public.kiyi_profiles where user_id=t) then raise exception 'Kullanıcı bulunamadı.';end if;
  if (select count(*) from public.kiyi_reports where reporter=u and created_at>now()-interval '1 hour')>=10 then raise exception 'Şikâyet sınırına ulaştın.';end if;
  insert into public.kiyi_reports(reporter,target,reason,details) values(u,t,payload->>'reason',coalesce(payload->>'details',''));return jsonb_build_object('ok',true);
 elsif action='verification' then
  if not coalesce((payload->>'consent')::boolean,false) or nullif(trim(payload->>'plate'),'') is null or not exists(select 1 from public.kiyi_profiles where user_id=u and nullif(trim(profile->>'plate'),'') is not null) or regexp_replace(upper(payload->>'plate'),'\s','','g')<>(select regexp_replace(upper(profile->>'plate'),'\s','','g') from public.kiyi_profiles where user_id=u) then raise exception 'Plaka ve onay bilgilerini kontrol et.';end if;
  insert into public.kiyi_verifications(user_id,plate,note) values(u,payload->>'plate',payload->>'note') on conflict(user_id) do update set plate=excluded.plate,note=excluded.note,status='pending',created_at=now();return jsonb_build_object('ok',true);
 elsif action='post_create' then
