 usage=jsonb_build_object('as_of',now(),'threshold_percent',75,'automatic_delivery','admin_panel','note','Veritabanı bu projenin tamamını kapsar. Depolama bu projenin ölçümüdür; organizasyon toplamı daha yüksek olabilir. Veri çıkışı, Auth MAU ve Realtime için resmî kullanım kaynağı bağlanmalıdır. MB/GB hesabı ondalık bayt üzerinden erken uyarı verir; Supabase kullanım ekranı esastır.','items',(select jsonb_agg(jsonb_build_object('metric',q.metric,'label',q.label,'quota',q.quota,'unit',q.unit,'used',case when s.observed_at>now()-interval '1 hour' and (s.period_end is null or now()between s.period_start and s.period_end) then s.used else null end,'observed_at',s.observed_at,'source',coalesce(s.source,'not_connected'),'warning_at',q.quota*.75,'status',case when s.used is null or s.observed_at is null or s.observed_at<=now()-interval '1 hour' or (s.period_end is not null and not(now()between s.period_start and s.period_end))then 'unknown' when s.used>=q.quota*.75 then 'warning' else 'normal' end)order by q.n)from(values(1,'database','Veritabanı',500000000::numeric,'bytes'),(2,'storage','Dosya depolama',1000000000::numeric,'bytes'),(3,'egress','Aylık veri çıkışı',5000000000::numeric,'bytes'),(4,'cached_egress','Aylık önbellek veri çıkışı',5000000000::numeric,'bytes'),(5,'auth_mau','Aylık aktif Auth kullanıcı',50000::numeric,'count'),(6,'realtime_messages','Aylık Realtime mesajı',2000000::numeric,'count'),(7,'realtime_connections','Tepe Realtime bağlantısı',200::numeric,'count'))q(n,metric,label,quota,unit)left join kiyi_private.ops_usage_readings s on s.metric=q.metric));
