select jsonb_strip_nulls(jsonb_build_object('name',p.profile->'name','ownerName',p.profile->'ownerName','plate',p.profile->'plate','car',p.profile->'car','year',p.profile->'year','color',p.profile->'color','area',p.profile->'area','bio',p.profile->'bio','instagram',p.profile->'instagram','tiktok',p.profile->'tiktok','status',p.profile->'status','avatar',case when jsonb_typeof(p.profile->'photos')='array' then (select to_jsonb(s.path) from jsonb_array_elements_text(p.profile->'photos')with ordinality s(path,n) where not exists(select 1 from kiyi_private.ops_media where path=s.path and hidden) order by s.n limit 1) else case when exists(select 1 from kiyi_private.ops_media where path=p.profile->>'avatar' and hidden) then null else p.profile->'avatar' end end,'photo',case when exists(select 1 from kiyi_private.ops_media where path=p.profile->>'photo' and hidden) then null else p.profile->'photo' end))||jsonb_build_object('vehicleKind',coalesce((select kind from public.kiyi_vehicles where owner=p.user_id and is_primary and deleted_at is null),'car'),'vehicleCount',(select count(*) from public.kiyi_vehicles g where g.owner=p.user_id and g.deleted_at is null and (g.model_id is not null or nullif(g.plate,'') is not null) and (auth.uid()=p.user_id or (g.visibility='public' and (kiyi_private.premium(auth.uid()) or not exists(select 1 from public.kiyi_privacy q where q.user_id=p.user_id and q.ghost))))),'id',p.user_id,'username',p.username,'searchable',p.searchable,'verified',coalesce(e.verified,false),'plateStyle',coalesce(a.plate_style,'classic'),'plateNames',coalesce(a.plate_names,'{}'),'paint',coalesce(a.paint,'#ffffff'),'vehicleModel',a.vehicle_model,'avatarFrame',coalesce(a.frame,'none'),'serverProfile',true,'supabaseProfile',true,'publicProfile',true,'sharing',false,'featured',coalesce(e.featured,false),'featuredRank',coalesce(e.featured_rank,100),'online',exists(select 1 from public.kiyi_positions l where l.user_id=u and l.received_at>now()-interval '90 seconds')) from public.kiyi_profiles p left join public.kiyi_appearance a on a.user_id=p.user_id left join public.kiyi_entitlements e on e.user_id=p.user_id where p.user_id=u and kiyi_private.account_active(u)
$function$
CREATE OR REPLACE FUNCTION kiyi_private.command_stage3(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare u uuid=auth.uid();t uuid;v public.kiyi_vehicles;m public.kiyi_vehicle_models;r jsonb;a jsonb;e record;p public.kiyi_vehicle_part_products;cost int=0;rid uuid;ref text;version int;initial_color text;nextid uuid;
begin
 perform kiyi_private.command_stage2('__stage7_guard','{}');
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 if payload?'vehicle_id' and not exists(select 1 from public.kiyi_vehicles where id=(payload->>'vehicle_id')::uuid and owner=u and deleted_at is null) then raise exception 'Araç bulunamadı.' using errcode='42501';end if;
 if action='directory' and payload?'plate' then
 r=kiyi_private.command_stage2('directory',payload);
 for e in select g.* from public.kiyi_vehicles g where g.plate_key=regexp_replace(upper(payload->>'plate'),'[[:space:]]','','g') and g.deleted_at is null and g.visibility='public' and g.owner<>u loop
 a=kiyi_private.command('garage_public',jsonb_build_object('target',e.owner));
 if exists(select 1 from jsonb_array_elements(a->'vehicles') z where z->>'id'=e.id::text) and not exists(select 1 from jsonb_array_elements(r->'profiles') z where z->>'id'=e.owner::text) then
 r=jsonb_set(r,'{profiles}',(r->'profiles')||jsonb_build_array(kiyi_private.person(e.owner)||jsonb_build_object('plate',e.plate,'vehicleKind',e.kind,'matchedVehicle',e.id)));
 end if;
 end loop;return r;
 elsif action in ('garage_list','garage_public') then
 t=case when action='garage_public' then (payload->>'target')::uuid else u end;
 if t is null or (t<>u and (not kiyi_private.account_active(t) or kiyi_private.blocked(u,t) or not exists(select 1 from public.kiyi_profiles where user_id=t and searchable and deleted_at is null) or (exists(select 1 from public.kiyi_privacy where user_id=t and ghost) and not kiyi_private.premium(u)) or (exists(select 1 from public.kiyi_positions pos join public.kiyi_regions reg on reg.id=pos.region where pos.user_id=t and reg.premium) and not kiyi_private.premium(u) and not exists(select 1 from public.kiyi_entitlements where user_id=t and featured)))) then return jsonb_build_object('vehicles','[]'::jsonb,'count',0);end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at),'[]') into r from(select g.id,g.model_id,g.kind,g.plate,g.is_primary,g.visibility,g.created_at,c.appearance,c.version,cat.name,cat.ready from public.kiyi_vehicles g join public.kiyi_vehicle_customizations c on c.vehicle_id=g.id left join public.kiyi_vehicle_models cat on cat.id=g.model_id where g.owner=t and g.deleted_at is null and (t=u or g.visibility='public') and (g.model_id is not null or nullif(g.plate,'') is not null))q;
 return jsonb_build_object('vehicles',r,'count',jsonb_array_length(r),'models',case when t=u then(select jsonb_agg(to_jsonb(cat) order by name) from public.kiyi_vehicle_models cat) else '[]'::jsonb end,'products',case when t=u then(select coalesce(jsonb_agg(to_jsonb(pp)),'[]') from public.kiyi_vehicle_part_products pp) else '[]'::jsonb end);
 elsif action='vehicle_create' then
 initial_color=coalesce(payload->>'paint','#ffffff');if initial_color !~ '^#[0-9a-f]{6}$' then raise exception 'Geçersiz renk.';end if;
 r=kiyi_private.command_stage2(action,payload);
 update public.kiyi_vehicle_customizations set appearance=appearance||jsonb_build_object('paint',initial_color,'factoryPaint',initial_color) where vehicle_id=(r->>'id')::uuid;
 if not exists(select 1 from public.kiyi_vehicles where owner=u and is_primary and deleted_at is null and nullif(plate,'') is not null) then
 perform kiyi_private.command('vehicle_primary',jsonb_build_object('vehicle_id',r->>'id'));
 end if;
 return r;
 elsif action in ('vehicle_update','vehicle_delete','vehicle_primary') then
 select * into v from public.kiyi_vehicles where id=(payload->>'vehicle_id')::uuid and owner=u and deleted_at is null for update;
 if not found then raise exception 'Araç bulunamadı.' using errcode='42501';end if;
 if action='vehicle_delete' then
 if v.is_primary and exists(select 1 from public.kiyi_verifications where user_id=u and status='approved') then raise exception 'Doğrulanmış plakan için değişiklik talebi gönder.';end if;
 update public.kiyi_vehicles set deleted_at=now(),is_primary=false where id=v.id;
 if v.is_primary then
 select id into nextid from public.kiyi_vehicles where owner=u and deleted_at is null and id<>v.id and nullif(plate,'') is not null order by created_at limit 1;
 if nextid is not null then perform kiyi_private.command('vehicle_primary',jsonb_build_object('vehicle_id',nextid));
 else update public.kiyi_profiles set profile=profile||'{"plate":"","car":""}'::jsonb where user_id=u;update public.kiyi_appearance set vehicle_model=null where user_id=u;end if;
 end if;
 return jsonb_build_object('ok',true);
 elsif action='vehicle_primary' then
 if exists(select 1 from public.kiyi_verifications where user_id=u and status='approved' and plate is distinct from v.plate) then raise exception 'Doğrulanmış plakan için değişiklik talebi gönder.';end if;
 update public.kiyi_vehicles set is_primary=false where owner=u;
 update public.kiyi_vehicles set is_primary=true where id=v.id;
 select appearance into a from public.kiyi_vehicle_customizations where vehicle_id=v.id;
 update public.kiyi_appearance set vehicle_model=v.model_id,paint=coalesce(a->>'paint','#ffffff'),plate_style=coalesce(a->>'plateStyle','classic'),plate_names=coalesce(a->'plateNames','{}') where user_id=u;
 update public.kiyi_profiles set profile=profile||jsonb_build_object('plate',v.plate,'car',(select name from public.kiyi_vehicle_models where id=v.model_id)) where user_id=u;
 return jsonb_build_object('ok',true);
 else
 perform pg_advisory_xact_lock(hashtextextended('kiyi-plate-registry',0));
 if payload?'plate' then
 if length(trim(payload->>'plate')) not between 1 and 30 then raise exception 'Plakanı kontrol et.';end if;
 if v.is_primary then perform kiyi_private.command_stage2('profile',jsonb_build_object('profile',jsonb_build_object('plate',payload->>'plate')));
 else
 if exists(select 1 from public.kiyi_profiles where plate_key=regexp_replace(upper(payload->>'plate'),'[[:space:]]','','g')) then raise exception 'Plaka kayıtlı.' using errcode='23505';end if;
 update public.kiyi_vehicles set plate=payload->>'plate' where id=v.id;
 end if;end if;
 if payload?'visibility' then update public.kiyi_vehicles set visibility=payload->>'visibility' where id=v.id;end if;
 return jsonb_build_object('ok',true);
 end if;
 elsif action='motorcycle_customize' then
 select * into v from public.kiyi_vehicles where id=(payload->>'vehicle_id')::uuid and owner=u and deleted_at is null for update;
 select * into m from public.kiyi_vehicle_models where id=v.model_id and kind='motorcycle' and ready;
 if v.id is null or m.id is null then raise exception 'Motosiklet görseli ve katmanları henüz hazır değil.' using errcode='22023';end if;
 a=payload->'appearance';rid=(payload->>'request_id')::uuid;ref=v.id::text||':'||a::text;
 if rid is null or jsonb_typeof(a) is distinct from 'object' or octet_length(a::text)>4000 then raise exception 'Geçersiz işlem.';end if;
 if exists(select 1 from public.kiyi_ledger where owner=u and request_id=rid) then
 if not exists(select 1 from public.kiyi_ledger where owner=u and request_id=rid and reference=ref and kind='vehicle_parts') then raise exception 'İşlem kimliği daha önce kullanıldı.';end if;
 return jsonb_build_object('ok',true,'replayed',true);end if;
 select c.version into version from public.kiyi_vehicle_customizations c where c.vehicle_id=v.id;
 if version is distinct from (payload->>'version')::int then raise exception 'Araç güncellendi; yeniden yükle.' using errcode='PT409';end if;
 select coalesce(c.appearance->>'factoryPaint',c.appearance->>'paint','#ffffff') into initial_color from public.kiyi_vehicle_customizations c where c.vehicle_id=v.id;
 for e in select * from jsonb_each(a) loop
 if e.key='paint' and e.value=to_jsonb(initial_color) then continue;end if;
 select * into p from public.kiyi_vehicle_part_products where model_id=m.id and slot=e.key and value=e.value;
 if not found then raise exception 'Modelle uyumsuz parça.' using errcode='22023';end if;
 if not exists(select 1 from public.kiyi_inventory where owner=u and sku=p.sku) then cost=cost+p.credits;end if;
 end loop;
 update public.kiyi_wallets set balance=balance-cost where user_id=u and balance>=cost;
 if not found then raise exception 'Yeterli kredi yok.';end if;
 for e in select * from jsonb_each(a) loop
 insert into public.kiyi_inventory(owner,sku) select u,sku from public.kiyi_vehicle_part_products where model_id=m.id and slot=e.key and value=e.value on conflict do nothing;
 end loop;
 insert into public.kiyi_ledger(owner,request_id,amount,kind,reference) values(u,rid,-cost,'vehicle_parts',ref);
 update public.kiyi_vehicle_customizations set appearance=appearance||a,version=version+1,updated_at=now() where vehicle_id=v.id;
 if v.is_primary and a?'paint' then update public.kiyi_appearance set paint=a->>'paint' where user_id=u;end if;
 return jsonb_build_object('ok',true,'charged',cost);
 end if;
 return kiyi_private.command_stage2(action,payload);
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.social_person(person_id uuid, viewer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;begin
 if not kiyi_private.social_identity_visible(person_id,viewer) or not kiyi_private.account_active(person_id) then return null;end if;
 r=kiyi_private.person(person_id);
 if person_id<>viewer and not exists(select 1 from public.kiyi_vehicles g where g.owner=person_id and g.is_primary and kiyi_private.social_vehicle(g.id,viewer) is not null) then r=r-'plate'-'car'-'vehicleModel'-'plateStyle'-'plateNames'-'paint';end if;
 return r;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.comment_json(cid uuid, viewer uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select (to_jsonb(c)-'request_id')||jsonb_build_object('profile',kiyi_private.social_person(c.author,viewer),'mine',c.author=viewer,'canEdit',c.author=viewer,'canDelete',c.author=viewer or p.author=viewer)
 from public.kiyi_comments c join public.kiyi_posts p on p.id=c.post where c.id=cid and not c.hidden and kiyi_private.can_post(c.post,viewer) and not kiyi_private.blocked(viewer,c.author) and kiyi_private.social_person(c.author,viewer) is not null
$function$
CREATE OR REPLACE FUNCTION kiyi_private.social_identity_visible(owner_id uuid, viewer uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select owner_id=viewer or (not kiyi_private.blocked(owner_id,viewer) and (kiyi_private.premium(viewer) or (not exists(select 1 from public.kiyi_privacy where user_id=owner_id and ghost) and (exists(select 1 from public.kiyi_entitlements where user_id=owner_id and featured) or not exists(select 1 from public.kiyi_positions pos join public.kiyi_regions r on r.id=pos.region where pos.user_id=owner_id and r.premium)))))
$function$
CREATE OR REPLACE FUNCTION kiyi_private.can_post(pid uuid, viewer uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select kiyi_private.can_post_stage3(pid,viewer) and exists(select 1 from public.kiyi_posts where id=pid and kiyi_private.social_identity_visible(author,viewer))
$function$
CREATE OR REPLACE FUNCTION kiyi_private.revoke_plate_tags()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if TG_TABLE_NAME='kiyi_privacy' then
 if old.allow_plate_tags and not new.allow_plate_tags then update public.kiyi_posts p set vehicle_id=null,version=p.version+1,updated_at=now() from public.kiyi_vehicles v where p.vehicle_id=v.id and v.owner=new.user_id and p.author<>v.owner;end if;
 elsif TG_TABLE_NAME='kiyi_vehicles' then
 if new.visibility<>'public' or new.deleted_at is not null or new.plate_key is distinct from old.plate_key or new.owner is distinct from old.owner then update public.kiyi_posts set vehicle_id=null,version=version+1,updated_at=now() where vehicle_id=new.id and author<>new.owner;end if;
 else
 update public.kiyi_posts p set vehicle_id=null,version=p.version+1,updated_at=now() from public.kiyi_vehicles v where p.vehicle_id=v.id and ((p.author=new.owner and v.owner=new.target) or (p.author=new.target and v.owner=new.owner));
 end if;return new;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.social_rate(u uuid, k text, n integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h int;b timestamptz=date_trunc('minute',clock_timestamp());begin
 insert into kiyi_private.social_limits as l values(u,k,b,1) on conflict(actor,kind) do update set bucket=b,hits=case when l.bucket=b then l.hits+1 else 1 end returning hits into h;
 if h>n then raise sqlstate 'PT429' using message='Çok hızlı işlem yapıyorsun. Bir dakika sonra yeniden dene.';end if;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.command_stage7_final(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare u uuid=auth.uid();r jsonb;settings jsonb;target_id uuid;pid uuid;cid uuid;subject uuid;report_id uuid;subject_type text;why text;details_text text;note jsonb;k text;
begin
 if not kiyi_private.session_live(u) then raise exception 'Oturum geçersiz. Yeniden giriş yap.' using errcode='42501';end if;
 if action in ('ops_config','support_create','privacy_request','appeal_create','sanctions_mine','cases_mine','plate_change_request') then return kiyi_private.command_pre_garage(action,payload);end if;
 -- Preserve the existing suspension, deletion, maintenance and Auth guard.
 if action='bundle' then r=kiyi_private.command_stage5('bundle','{}');else perform kiyi_private.command_stage5('__stage7_guard','{}');end if;
 if jsonb_typeof(payload) is distinct from 'object' or octet_length(payload::text)>20000 then raise exception 'Geçersiz işlem.';end if;
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 if action='profile_photos' and coalesce(nullif(payload->>'target','')::uuid,u)<>u and kiyi_private.social_person((payload->>'target')::uuid,u) is null then raise exception 'Bu profil görünür değil.' using errcode='42501';end if;
 if action='bundle' then
 perform kiyi_private.sync_badges(u);
 return r||jsonb_build_object('notificationSettings',coalesce((select sp.settings from public.kiyi_social_preferences sp where sp.owner=u),'{}'), 'notifications',coalesce((select jsonb_agg(q.item order by q.created desc,q.id desc) from(select n.id,n.created,kiyi_private.notification_json(n.id,u) item from public.kiyi_notifications n where recipient=u and not kiyi_private.blocked(sender,u) order by created desc,id desc limit 200)q where q.item is not null),'[]'));
 elsif action='badges' then
 target_id=coalesce(nullif(payload->>'target','')::uuid,u);
 if not kiyi_private.account_active(target_id) or kiyi_private.social_person(target_id,u) is null then raise exception 'Bu profil görünür değil.' using errcode='42501';end if;
 -- Only reconcile own achievements; foreign reads never generate notifications.
 if target_id=u then perform kiyi_private.sync_badges(u);end if;
 return jsonb_build_object('badges',coalesce((select jsonb_agg(jsonb_build_object('code',b.code,'earned_at',b.earned_at) order by b.earned_at,b.code) from public.kiyi_badges b where b.owner=target_id and (code<>'verified' or exists(select 1 from public.kiyi_entitlements where user_id=target_id and verified))),'[]'));
 elsif action='notification_settings' then
 if payload?'settings' then
 settings=payload->'settings';
 if jsonb_typeof(settings)<>'object' or exists(select 1 from jsonb_each(settings)e where e.key not in ('follow','like','comment','tag','badge') or jsonb_typeof(e.value)<>'boolean') then raise exception 'Geçersiz bildirim tercihi.';end if;
 perform kiyi_private.social_rate(u,'notification_settings',20);
 insert into public.kiyi_social_preferences(owner,settings) values(u,settings) on conflict(owner) do update set settings=public.kiyi_social_preferences.settings||excluded.settings;
 end if;
 return jsonb_build_object('settings',coalesce((select sp.settings from public.kiyi_social_preferences sp where sp.owner=u),'{}'),'push_available',false);
 elsif action in ('notification_open','read') then
 note=kiyi_private.notification_json((payload->>'id')::uuid,u);if note is null then raise exception 'Bildirim bulunamadı veya artık görünür değil.' using errcode='42501';end if;
 update public.kiyi_notifications set read_at=coalesce(read_at,now()) where id=(payload->>'id')::uuid and recipient=u;
 return jsonb_build_object('ok',true,'notification',note);
 elsif action in ('content_report','post_report') then
 perform kiyi_private.social_rate(u,'report',10);
 if (select count(*) from public.kiyi_reports where reporter=u and created_at>now()-interval '1 hour')>=10 then raise exception 'Saatlik şikâyet sınırına ulaştın.' using errcode='PT429';end if;
 subject_type=case when action='post_report' then 'post' else payload->>'kind' end;subject=(payload->>'id')::uuid;why=trim(payload->>'reason');details_text=trim(coalesce(payload->>'details',''));
 if why='Taciz' then why='Taciz veya hakaret';end if;
 if why is null or why not in ('Spam','Taciz veya hakaret','Uygunsuz içerik','Sahte hesap','Gizlilik ihlali','Diğer') or length(details_text)>450 then raise exception 'Şikâyet bilgilerini kontrol et.';end if;
 if subject_type='post' then select author,id into target_id,pid from public.kiyi_posts where id=subject and kiyi_private.can_post(id,u);
 elsif subject_type='comment' then select author,post,id into target_id,pid,cid from public.kiyi_comments where id=subject and kiyi_private.comment_json(id,u) is not null;
 else raise exception 'Geçersiz içerik türü.';end if;
 if target_id is null or target_id=u then raise exception 'Bu içeriği şikâyet edemezsin.' using errcode='42501';end if;
 select id into report_id from public.kiyi_reports where reporter=u and subject_kind=subject_type and subject_id=subject and status in ('pending','in_review') order by created_at desc limit 1;
 if report_id is null then insert into public.kiyi_reports(reporter,target,reason,details,subject_kind,subject_id) values(u,target_id,why,details_text,subject_type,subject) returning id into report_id;end if;
 return jsonb_build_object('ok',true,'id',report_id,'status',(select status from public.kiyi_reports where id=report_id));
 elsif action='my_reports' then
 return jsonb_build_object('reports',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from(select id,subject_kind,subject_id,reason,status,created_at from public.kiyi_reports where reporter=u order by created_at desc,id desc limit 50)q),'[]'));
 end if;
 return kiyi_private.command_stage5(action,payload);
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.post_json_stage4(pid uuid, viewer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;v jsonb;p public.kiyi_posts;begin
 r=kiyi_private.post_json_stage3(pid,viewer);if r is null then return null;end if;
 select * into p from public.kiyi_posts where id=pid;
 v=kiyi_private.social_vehicle(p.vehicle_id,viewer);
 r=jsonb_set(r,'{comments}',coalesce((select jsonb_agg(item) from jsonb_array_elements(r->'comments') item where kiyi_private.social_identity_visible((item->>'author')::uuid,viewer)),'[]'::jsonb));
 r=(r-'vehicle_id'-'request_id')||jsonb_build_object('vehicle',v,'vehicleHidden',p.vehicle_id is not null and v is null,'commentCount',(select count(*) from public.kiyi_comments where post=pid and not hidden and kiyi_private.account_active(author) and not kiyi_private.blocked(viewer,author) and kiyi_private.social_identity_visible(author,viewer)));
 -- A public post is not a grant to expose an author's private primary-vehicle plate.
 if p.author<>viewer and not exists(select 1 from public.kiyi_vehicles g where g.owner=p.author and g.is_primary and kiyi_private.social_vehicle(g.id,viewer) is not null) then
 r=jsonb_set(r,'{profile}',(r->'profile')-'plate'-'car'-'vehicleModel'-'plateStyle'-'plateNames'-'paint');
 end if;
 return r;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.post_json(pid uuid, viewer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;v public.kiyi_vehicles;p public.kiyi_posts;begin
 r=kiyi_private.post_json_stage4(pid,viewer);if r is null then return null;end if;
 select * into p from public.kiyi_posts where id=pid;select * into v from public.kiyi_vehicles where id=p.vehicle_id;
 if v.owner<>p.author and not coalesce((select allow_plate_tags from public.kiyi_privacy where user_id=v.owner),false) then r=r||jsonb_build_object('vehicle',null,'vehicleHidden',true);end if;
 return r||jsonb_build_object('following',exists(select 1 from public.kiyi_follows where follower=viewer and target=p.author),'canUntag',p.vehicle_id is not null and (p.author=viewer or v.owner=viewer),'comments',coalesce((select jsonb_agg(q.data order by q.created,q.id) from(select c.id,c.created,kiyi_private.comment_json(c.id,viewer) as data from public.kiyi_comments c where c.post=pid and kiyi_private.comment_json(c.id,viewer) is not null order by c.created,c.id limit 100)q),'[]'));
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.comment_ops(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare u uuid=auth.uid();pid uuid;cid uuid;rid uuid;vid uuid;v public.kiyi_vehicles;p public.kiyi_posts;c public.kiyi_comments;txt text;r jsonb;z jsonb;results jsonb='[]';ids uuid[];n int;next_cursor jsonb;enabled boolean;ms bigint=(extract(epoch from clock_timestamp())*1000)::bigint;
begin
 if action in ('comment_edit','comment_delete','comment_profile') then select * into c from public.kiyi_comments where id=(payload->>'comment_id')::uuid for update;pid=c.post;else pid=(payload->>'id')::uuid;end if;
 if action='comment_delete' then
 if c.id is null or not(c.author=u or exists(select 1 from public.kiyi_posts where id=pid and author=u)) then raise exception 'Yorumu silemezsin.' using errcode='42501';end if;
 perform kiyi_private.social_rate(u,'manage',60);delete from public.kiyi_comments where id=c.id;return jsonb_build_object('ok',true,'post',kiyi_private.post_json(pid,u));end if;
 if pid is null or not kiyi_private.can_post(pid,u) then raise exception 'Gönderi bulunamadı.' using errcode='42501';end if;
 if action='comment_profile' then r=kiyi_private.comment_json(c.id,u);if r is null then raise exception 'Yorum görünür değil.' using errcode='42501';end if;return jsonb_build_object('profile',r->'profile');
 elsif action='comments' then
 n=least(50,greatest(1,coalesce((payload->>'limit')::int,30)));
 select array_agg(q.id order by q.created,q.id) into ids from(select s.id,s.created from public.kiyi_comments s where s.post=pid and kiyi_private.comment_json(s.id,u) is not null and (not(payload?'cursor') or (s.created,s.id)>((payload->'cursor'->>'created')::bigint,(payload->'cursor'->>'id')::uuid)) order by s.created,s.id limit n+1)q;
 if ids is not null then foreach cid in array ids[1:n] loop results=results||jsonb_build_array(kiyi_private.comment_json(cid,u));end loop;if cardinality(ids)>n then select jsonb_build_object('created',created,'id',id) into next_cursor from public.kiyi_comments where id=ids[n];end if;end if;
 return jsonb_build_object('comments',results,'next',next_cursor,'count',(kiyi_private.post_json(pid,u)->>'commentCount')::int);
 end if;
 txt=btrim(regexp_replace(coalesce(payload->>'text',''),'[[:space:]]+',' ','g'));
 if length(txt) not between 1 and 500 then raise exception 'Yorum 1–500 karakter olmalı.';end if;
 if action='comment_edit' then
 if c.author is distinct from u or c.hidden then raise exception 'Yorumu düzenleyemezsin.' using errcode='42501';end if;
 if (payload->>'version')::int is distinct from c.version then raise sqlstate 'PT409' using message='Yorum değişmiş. Yeniden yükle.';end if;
 else
 rid=nullif(payload->>'request_id','')::uuid;
 if rid is not null then select * into c from public.kiyi_comments where author=u and request_id=rid;if found then if c.post<>pid or c.text<>txt then raise exception 'İşlem kimliği başka yorumda kullanıldı.';end if;return jsonb_build_object('post',kiyi_private.post_json(pid,u));end if;end if;
 end if;
 if exists(select 1 from public.kiyi_comments s where s.author=u and s.created>ms-60000 and lower(btrim(regexp_replace(s.text,'[[:space:]]+',' ','g')))=lower(txt) and (action='comment' or s.id<>c.id)) then raise sqlstate 'PT429' using message='Aynı yorumu tekrar göndermek için biraz bekle.';end if;
 perform kiyi_private.social_rate(u,'comment',20);
 if action='comment_edit' then update public.kiyi_comments set text=txt,version=version+1,updated_at=now() where id=c.id;
 else insert into public.kiyi_comments(post,author,text,created,request_id) values(pid,u,txt,ms,rid);end if;
 return jsonb_build_object('post',kiyi_private.post_json(pid,u));
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.command_stage5(action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare u uuid=auth.uid();pid uuid;cid uuid;rid uuid;vid uuid;v public.kiyi_vehicles;p public.kiyi_posts;c public.kiyi_comments;txt text;r jsonb;z jsonb;results jsonb='[]';ids uuid[];n int;next_cursor jsonb;enabled boolean;ms bigint=(extract(epoch from clock_timestamp())*1000)::bigint;
begin
 perform kiyi_private.command_stage4('__stage7_guard','{}');
 perform pg_advisory_xact_lock(hashtextextended('kiyi:'||u::text,0));
 if action='tag_settings' then
 if payload?'enabled' then
 if jsonb_typeof(payload->'enabled')<>'boolean' then raise exception 'Geçersiz izin.';end if;
 perform kiyi_private.social_rate(u,'settings',10);
 update public.kiyi_privacy set allow_plate_tags=(payload->>'enabled')::boolean where user_id=u;
 end if;
 return jsonb_build_object('enabled',(select allow_plate_tags from public.kiyi_privacy where user_id=u));
 elsif action in ('directory','tag_search') and payload?'plate' then
 if action='tag_search' then perform kiyi_private.social_rate(u,'tag_search',30);end if;
 r=kiyi_private.command_stage4('directory',payload);
 for v in select g.* from public.kiyi_vehicles g where g.deleted_at is null and g.plate_key=regexp_replace(upper(payload->>'plate'),'[[:space:]]','','g') and g.owner<>u loop
 if kiyi_private.social_vehicle(v.id,u) is not null and exists(select 1 from jsonb_array_elements(r->'profiles') x where x->>'id'=v.owner::text) then
 if action='directory' then results=results||jsonb_build_array(kiyi_private.social_person(v.owner,u)||jsonb_build_object('plate',v.plate,'matchedVehicle',v.id,'vehicleKind',v.kind));
 elsif coalesce((select allow_plate_tags from public.kiyi_privacy where user_id=v.owner),false) then results=results||jsonb_build_array(kiyi_private.social_vehicle(v.id,u)||jsonb_build_object('profile',kiyi_private.social_person(v.owner,u)));end if;
 end if;end loop;
 return jsonb_build_object(case when action='directory' then 'profiles' else 'vehicles' end,results);
 elsif action in ('post_create','post_edit') then
 if action='post_edit' then select * into p from public.kiyi_posts where id=(payload->>'id')::uuid and author=u for update;if not found then raise exception 'Gönderiyi düzenleyemezsin.' using errcode='42501';end if;end if;
 vid=case when payload?'vehicle_id' then nullif(payload->>'vehicle_id','')::uuid else p.vehicle_id end;
 if vid is not null then
 select * into v from public.kiyi_vehicles where id=vid and deleted_at is null for share;
 if not found then raise exception 'Araç bulunamadı.' using errcode='42501';end if;
 if v.owner<>u then
 perform 1 from public.kiyi_privacy where user_id=v.owner and allow_plate_tags for share;
 if not found or kiyi_private.social_vehicle(v.id,u) is null then raise exception 'Bu plaka etiketlemeye açık değil.' using errcode='42501';end if;
 end if;end if;
 -- Existing Stage 4 validates all other fields; attach the validated tag atomically.
 if action='post_create' and payload?'request_id' then
 select * into p from public.kiyi_posts where author=u and request_id=(payload->>'request_id')::uuid;
 if found then
 if p.vehicle_id is distinct from vid then raise exception 'İşlem kimliği başka gönderide kullanıldı.';end if;
 update public.kiyi_posts set vehicle_id=null where id=p.id;
 end if;end if;
 if action='post_edit' then update public.kiyi_posts set vehicle_id=null where id=p.id;end if;
 r=kiyi_private.command_stage4(action,payload-'vehicle_id');pid=(r->'post'->>'id')::uuid;
 update public.kiyi_posts set vehicle_id=vid where id=pid;
 return r||jsonb_build_object('post',kiyi_private.post_json(pid,u));
 elsif action='post_untag' then
 perform kiyi_private.social_rate(u,'manage',60);
 select s.* into p from public.kiyi_posts s join public.kiyi_vehicles g on g.id=s.vehicle_id where s.id=(payload->>'id')::uuid and (s.author=u or g.owner=u) for update of s;
 if not found then raise exception 'Etiketi kaldıramazsın.' using errcode='42501';end if;
 update public.kiyi_posts set vehicle_id=null,version=version+1,updated_at=now() where id=p.id;return jsonb_build_object('ok',true);
 elsif action='tagged_posts' then
 return jsonb_build_object('posts',coalesce((select jsonb_agg(kiyi_private.post_json(q.id,u)) from(select s.id from public.kiyi_posts s join public.kiyi_vehicles g on g.id=s.vehicle_id where g.owner=u and s.author<>u and kiyi_private.can_post(s.id,u) order by s.created desc,s.id desc limit 30)q),'[]'));
 elsif action='like' then
 if jsonb_typeof(payload->'like') is distinct from 'boolean' then raise exception 'Geçersiz beğeni.';end if;
 perform kiyi_private.social_rate(u,'like',60);return kiyi_private.command_stage4(action,payload);
 elsif action='follow' then
 if jsonb_typeof(payload->'enabled') is distinct from 'boolean' then raise exception 'Geçersiz takip.';end if;
 perform kiyi_private.social_rate(u,'follow',30);
 if (payload->>'enabled')::boolean and (not kiyi_private.account_active((payload->>'target')::uuid) or not kiyi_private.social_identity_visible((payload->>'target')::uuid,u)) then raise exception 'Bu hesap görünür değil.' using errcode='42501';end if;
 return kiyi_private.command_stage4(action,payload);
 elsif action in ('comment','comment_edit','comment_delete','comments','comment_profile') then

 return kiyi_private.comment_ops(action,payload);
 end if;
 return kiyi_private.command_stage4(action,payload);
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.social_notify(recipient_id uuid, actor_id uuid, event_type text, event_id text, pid uuid DEFAULT NULL::uuid, cid uuid DEFAULT NULL::uuid, vid uuid DEFAULT NULL::uuid, badge text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if event_type not in ('follow','like','comment','tag','badge') or recipient_id is null or actor_id is null or (recipient_id=actor_id and event_type<>'badge') or kiyi_private.blocked(recipient_id,actor_id) or not kiyi_private.account_active(recipient_id) then return;end if;
 if coalesce((select (settings->>event_type)::boolean from public.kiyi_social_preferences where owner=recipient_id),true)=false then return;end if;
 insert into public.kiyi_notifications(recipient,sender,kind,created,post_id,comment_id,vehicle_id,badge_code,event_key) values(recipient_id,actor_id,event_type,(extract(epoch from clock_timestamp())*1000)::bigint,pid,cid,vid,badge,event_type||':'||event_id) on conflict(recipient,event_key) where event_key is not null do nothing;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.sync_badges(person_id uuid, notify boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare codes text[]='{}';code_id text;new_code text;posts_count int;
begin
 if not kiyi_private.account_active(person_id) then return;end if;
 if exists(select 1 from public.kiyi_vehicles where owner=person_id and deleted_at is null and (model_id is not null or plate_key is not null)) then codes=array_append(codes,'first_vehicle');end if;
 select count(*) into posts_count from (select 1 from public.kiyi_posts where author=person_id and not hidden limit 10)x;
 if posts_count>=1 then codes=array_append(codes,'first_post');end if;if posts_count>=10 then codes=array_append(codes,'ten_posts');end if;
 if (select count(*) from (select 1 from public.kiyi_follows f where target=person_id and kiyi_private.account_active(follower) and not kiyi_private.blocked(follower,target) limit 100)x)>=100 then codes=array_append(codes,'hundred_followers');end if;
 if exists(select 1 from public.kiyi_entitlements where user_id=person_id and verified) then codes=array_append(codes,'verified');end if;
 foreach code_id in array codes loop
 new_code=null;insert into public.kiyi_badges(owner,code) values(person_id,code_id) on conflict do nothing returning code into new_code;
 if new_code is not null and notify then perform kiyi_private.social_notify(person_id,person_id,'badge',code_id,null,null,null,code_id);end if;
 end loop;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.social_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare owner_id uuid;begin
 if tg_table_name='kiyi_follows' then
 perform kiyi_private.social_notify(new.target,new.follower,'follow',new.follower::text);perform kiyi_private.sync_badges(new.target);
 elsif tg_table_name='kiyi_likes' then
 select author into owner_id from public.kiyi_posts where id=new.post;
 perform kiyi_private.social_notify(owner_id,new.person,'like',new.person::text||':'||new.post::text,new.post);
 elsif tg_table_name='kiyi_comments' then
 select author into owner_id from public.kiyi_posts where id=new.post;
 perform kiyi_private.social_notify(owner_id,new.author,'comment',new.id::text,new.post,new.id);
 elsif tg_table_name='kiyi_posts' then
 if tg_op='INSERT' then perform kiyi_private.sync_badges(new.author);end if;
 if new.vehicle_id is not null then
 select owner into owner_id from public.kiyi_vehicles where id=new.vehicle_id;
 perform kiyi_private.social_notify(owner_id,new.author,'tag',new.id::text||':'||new.vehicle_id::text,new.id,null,new.vehicle_id);
 end if;
 elsif tg_table_name='kiyi_vehicles' then perform kiyi_private.sync_badges(new.owner);
 elsif tg_table_name='kiyi_entitlements' then perform kiyi_private.sync_badges(new.user_id);
 end if;return new;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.notification_json(note_id uuid, viewer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.kiyi_notifications;p jsonb;begin
 select * into n from public.kiyi_notifications where id=note_id and recipient=viewer;
 if not found or kiyi_private.blocked(n.sender,viewer) then return null;end if;
 if n.event_key is null then return to_jsonb(n);end if;
 p=kiyi_private.social_person(n.sender,viewer);if p is null then return null;end if;
 if n.post_id is not null and not kiyi_private.can_post(n.post_id,viewer) then return null;end if;
 if n.kind='comment' and kiyi_private.comment_json(n.comment_id,viewer) is null then return null;end if;
 if n.kind='tag' and not exists(select 1 from public.kiyi_posts where id=n.post_id and vehicle_id=n.vehicle_id) then return null;end if;
 if n.kind='badge' and n.badge_code='verified' and not exists(select 1 from public.kiyi_entitlements where user_id=viewer and verified) then return null;end if;
 return (to_jsonb(n)-'event_key')||jsonb_build_object('senderProfile',p);
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.session_live(viewer uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select viewer is not null and viewer=auth.uid() and (
 -- Owner-run transaction fixtures are not externally usable Auth tokens.
 (session_user='postgres' and coalesce(auth.jwt()->>'role','')='')
 or exists(select 1 from auth.sessions s where s.id=nullif(auth.jwt()->>'session_id','')::uuid and s.user_id=viewer and (s.not_after is null or s.not_after>now())))
$function$
CREATE OR REPLACE FUNCTION kiyi_private.social_vehicle(vid uuid, viewer uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select jsonb_build_object('id',g.id,'owner',g.owner,'model_id',g.model_id,'name',coalesce(m.name,case when g.kind='motorcycle' then 'Motosiklet' else 'Otomobil' end),'kind',g.kind,'plate',g.plate,'is_primary',g.is_primary,'appearance',c.appearance,'ready',coalesce(m.ready,false),'visibility',g.visibility)
 from public.kiyi_vehicles g left join public.kiyi_vehicle_models m on m.id=g.model_id join public.kiyi_vehicle_customizations c on c.vehicle_id=g.id
 where g.id=vid and g.deleted_at is null and kiyi_private.account_active(g.owner) and (g.owner=viewer or (g.visibility='public' and not kiyi_private.blocked(g.owner,viewer) and exists(select 1 from public.kiyi_profiles where user_id=g.owner and searchable and deleted_at is null) and (kiyi_private.premium(viewer) or not exists(select 1 from public.kiyi_privacy where user_id=g.owner and ghost)) and (kiyi_private.premium(viewer) or exists(select 1 from public.kiyi_entitlements where user_id=g.owner and featured) or not exists(select 1 from public.kiyi_positions pos join public.kiyi_regions r on r.id=pos.region where pos.user_id=g.owner and r.premium))))
$function$
CREATE OR REPLACE FUNCTION kiyi_private.review_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare kind text=case when tg_table_name='kiyi_posts' then 'post' else 'comment' end;why text;
begin
 if new.hidden then return new;end if;
 if tg_op='UPDATE' and new.text is not distinct from old.text and to_jsonb(new)->'media' is not distinct from to_jsonb(old)->'media' then return new;end if;
 if lower(new.text) ~ '(seni|sizi)[[:space:]]+(öldür|oldur)' then why='Olası tehdit';
 elsif new.text ~ '0?5[0-9]{2}[[:space:]-]*[0-9]{3}[[:space:]-]*[0-9]{2}[[:space:]-]*[0-9]{2}' then why='Olası kişisel bilgi ifşası';
 elsif length(new.text)-length(replace(new.text,'https://',''))>40 then why='Olası bağlantı spamı';
 elsif kind='post' and nullif(to_jsonb(new)->>'media','') is not null then why='Görsel/video otomatik sınıflandırıcısı bağlı değil; insan incelemesi gerekli';
 else return new;end if;
 if not exists(select 1 from public.kiyi_reports where source='automated' and subject_kind=kind and subject_id=new.id and status in ('pending','in_review')) then
 -- reporter is the record owner, NOT a claim that the author filed a complaint.
 insert into public.kiyi_reports(reporter,target,reason,details,subject_kind,subject_id,source) values(new.author,new.author,'Diğer','OTOMATİK İNCELEME — kullanıcı şikâyeti değildir. '||why,kind,new.id,'automated');
 end if;return new;
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.health_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n bigint;removed bigint;begin
 perform kiyi_private.delivery_maintenance();
 perform pg_advisory_xact_lock(hashtextextended('kiyi-stage8-health',0));
 -- Only new anonymous fixed-code client telemetry; not customer/account/audit data.
 delete from kiyi_private.ops_events where kind='client' and code in ('client_error','api_error','media_error','map_error','notification_error','offline') and created_at<now()-interval '30 days';get diagnostics removed=row_count;
 select count(*) into n from kiyi_private.ops_events where kind='client' and code in ('api_error','media_error','map_error') and created_at>now()-interval '15 minutes';
 if n>=10 and not exists(select 1 from kiyi_private.ops_jobs where kind='health_alert' and created_at>now()-interval '1 hour') then
 insert into kiyi_private.ops_jobs(kind,status,details) values('health_alert','pending',jsonb_build_object('code','CLIENT_FAILURE_THRESHOLD','window_minutes',15,'count',n,'delivery','admin_health_queue'));
 end if;return jsonb_build_object('anonymous_events_expired',removed,'recent_failures',n);
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.delivery_settings(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid=auth.uid();k text;e jsonb;begin
 if not kiyi_private.session_live(u) or not kiyi_private.account_active(u) then raise exception 'Giriş yapmalısın.' using errcode='42501';end if;
 perform kiyi_private.social_rate(u,'delivery_settings',15);
 if exists(select 1 from jsonb_object_keys(payload) key where key not in ('email','push','events')) then raise exception 'Geçersiz tercih.' using errcode='22023';end if;
 foreach k in array array['email','push'] loop if payload?k and jsonb_typeof(payload->k)<>'boolean' then raise exception 'Geçersiz tercih.' using errcode='22023';end if;end loop;
 e=coalesce(payload->'events','{}');
 if jsonb_typeof(e)<>'object' or exists(select 1 from jsonb_each(e) x where x.key not in ('follow','like','comment','tag','badge','gift','song','verification','security','admin','account_deletion') or jsonb_typeof(x.value)<>'boolean') then raise exception 'Geçersiz olay tercihi.' using errcode='22023';end if;
 insert into kiyi_private.delivery_preferences(owner) values(u) on conflict do nothing;
 update kiyi_private.delivery_preferences p set email=coalesce((payload->>'email')::boolean,p.email),push=coalesce((payload->>'push')::boolean,p.push),events=p.events||e,updated_at=now() where owner=u;
 -- Revocation permanently cancels old pending jobs; re-enabling does not replay them.
 update kiyi_private.delivery_outbox j set state='cancelled',lease=null,lease_until=null,last_code='preference_revoked' where recipient=u and state in ('waiting_configuration','queued','retry','leased') and not kiyi_private.delivery_allowed(j);
 return jsonb_build_object('preferences',(select to_jsonb(p)-'owner' from kiyi_private.delivery_preferences p where owner=u),'email_available',coalesce((select value='true'::jsonb from kiyi_private.ops_settings where key='delivery_email_enabled'),false),'push_available',coalesce((select value='true'::jsonb from kiyi_private.ops_settings where key='delivery_push_enabled'),false));
end$function$
CREATE OR REPLACE FUNCTION kiyi_private.enqueue_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k text=new.kind;c text;begin
 if k='gift' and exists(select 1 from public.kiyi_gifts where id=new.gift_id and product='song') then k='song';end if;
 if k not in ('follow','like','comment','tag','badge','gift','song','verification','security','admin','account_deletion') then return new;end if;
 -- No historical backfill and no default opt-in. Outbox and source insert commit together.

 if not exists(select 1 from kiyi_private.delivery_preferences where owner=new.recipient and (email or push)) then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended('kiyi-delivery-capacity',0));
 if (select count(*) from (select 1 from kiyi_private.delivery_outbox where state in ('waiting_configuration','queued','retry','leased') limit 5000)x)>=5000
 or (select count(*) from (select 1 from kiyi_private.delivery_outbox where recipient=new.recipient and state in ('waiting_configuration','queued','retry','leased') limit 200)x)>=200 then
 insert into kiyi_private.ops_events(kind,code) select 'delivery','queue_capacity' where not exists(select 1 from kiyi_private.ops_events where kind='delivery' and code='queue_capacity' and created_at>now()-interval '1 hour');
 return new;end if;
 foreach c in array array['email','push'] loop
 if exists(select 1 from kiyi_private.delivery_preferences p where p.owner=new.recipient and (case when c='email' then p.email else p.push end) and coalesce((p.events->>k)::boolean,true)) then
 insert into kiyi_private.delivery_outbox(recipient,channel,kind,event_key,notification_id) values(new.recipient,c,k,'notification:'||new.id::text,new.id) on conflict do nothing;
 end if;end loop;return new;
end$function$
